/* SIMLAB Atomic Absorption Spectrometry training bench. All operation is simulated. */
const aasElements={
  Cu:{name:'Copper',symbol:'Cu',line:324.8,mode:'Flame',range:[0.05,5],standards:[0,.1,.25,.5,1],response:.18,check:0.42},
  Fe:{name:'Iron',symbol:'Fe',line:248.3,mode:'Flame',range:[0.1,10],standards:[0,.25,.5,1,2],response:.11,check:1.35},
  Zn:{name:'Zinc',symbol:'Zn',line:213.9,mode:'Flame',range:[0.02,2],standards:[0,.05,.1,.25,.5],response:.24,check:.28},
  Ca:{name:'Calcium',symbol:'Ca',line:422.7,mode:'Flame',range:[0.2,20],standards:[0,1,2.5,5,10],response:.035,check:4.6},
  Pb:{name:'Lead',symbol:'Pb',line:217.0,mode:'Furnace',range:[.005,.5],standards:[0,.025,.05,.1,.2],response:.75,check:.082}
};
const aasPrepNotes={
  'Drinking water':'Mix and inspect the sample; filter only when required by the method. Preserve and acidify only as specified by the approved sampling and analytical method. Standards, blank and sample should have compatible matrices.',
  'River water':'Homogenize and document whether the result is dissolved or total recoverable. Filtration and preservation change what is measured; follow the defined method and include a field or method blank as required.',
  'Soil digest':'Use an approved digestion procedure and suitable fume hood. Cool the digest, make it to volume, and account for every dilution. Include a digestion blank and a suitable reference or spike check.',
  'Food digest':'Use a validated food preparation and digestion method. Avoid contamination, cool before making to volume, and use a method blank plus a suitable reference material or spike recovery check.'
};
const aasParts=[
  ['lamp','Hollow-cathode lamp','A line source made with the analyte element. Excited atoms in its cathode emit narrow element-specific wavelengths. Select the matching lamp before measurement.'],
  ['nebulizer','Nebulizer','Draws liquid sample into a fine aerosol. Stable aspiration and clean tubing help keep sample delivery steady.'],
  ['spray','Spray chamber','Removes larger droplets so a finer aerosol reaches the atomizer; the drain must be working.'],
  ['burner','Burner head / atomizer','For flame AAS, the flame desolvates, vaporizes and atomizes the aerosol. The instrument measures absorption by ground-state atoms.'],
  ['furnace','Graphite furnace','For furnace AAS, a small aliquot is dried, charred and atomized inside a heated graphite tube. It is generally more sensitive and uses smaller sample volumes.'],
  ['mono','Monochromator','Selects the analytical line and rejects much of the unwanted light before it reaches the detector.'],
  ['detector','Detector and readout','Measures the decrease in lamp intensity after the light passes through the atom cloud. Absorbance is related to concentration through calibration.'],
  ['exhaust','Exhaust / fume hood','Captures hot combustion products and vapours. In a real laboratory, verify extraction before any flame operation.']
];
const aasDefault=()=>({element:'Cu',elementConfirmed:false,mode:'Flame',line:324.8,lampCurrent:5,slit:.5,matrix:'Drinking water',lamp:false,powered:false,warmed:false,exhaust:false,gasChecked:false,burnerSeated:false,drainChecked:false,tubeChecked:false,purgeChecked:false,flame:false,zeroed:false,calibrated:false,sampleRun:false,methodNeedsReview:false,runState:'error',running:false,standards:[0,.1,.25,.5,1],stock:100,finalVolume:50,sequenceUnknown:false,sequenceSampleId:'',sequenceDilution:1,sequenceReplicates:3,runs:[],teacherAssignments:[],reviewedSubmissions:[],classroomAssignment:null,studentName:'',sampleId:'WATER-01',lastAssignmentCode:'',lastSubmissionCode:'',selectedPart:'lamp',status:'Begin with the safety and instrument checks. No real instrument or gas is controlled.'});
let aas=aasDefault(),aasWarmTimer=null,aasRunTimer=null;
try{const saved=JSON.parse(localStorage.getItem('simlab-aas-v1')||'null');if(saved&&typeof saved==='object'){aas={...aas,...saved,runs:Array.isArray(saved.runs)?saved.runs:[]};if(typeof saved.elementConfirmed!=='boolean')aas.elementConfirmed=!!saved.element;}}catch{}
if(aas.running){aas.running=false;aas.operation='';aas.runState='error';aas.status='The previous simulated run was interrupted. Check setup and run it again.';}
const aasCurrent=()=>aasElements[aas.element]||aasElements.Cu;
function aasLampState(ready){if(aas.running)return 'running';if(aas.runState==='error'||aas.methodNeedsReview||!ready||!aas.flame)return 'error';if(aas.runState==='complete')return 'complete';return 'ready';}
const aasLampLabels={running:'RUNNING',complete:'COMPLETE',ready:'READY',error:'CHECK SETUP'};
function aasStore(){try{localStorage.setItem('simlab-aas-v1',JSON.stringify(aas));}catch{}}
function aasEncodePacket(payload){const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return 'SIMLAB-AAS1:'+btoa(binary);}
function aasEncodeCompactAssignment({id,element,sampleLabel,signal}){const bytes=new TextEncoder().encode(JSON.stringify([id,element,sampleLabel,signal]));let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return 'A1:'+btoa(binary);}
function aasDecodePacket(code){const text=String(code||'').trim(),compact=text.startsWith('A1:');if(!compact&&!text.startsWith('SIMLAB-AAS1:'))throw new Error('This is not a SIMLAB AAS assignment code.');const payload=compact?text.slice(3):text.slice(12),binary=atob(payload),decoded=JSON.parse(new TextDecoder().decode(Uint8Array.from(binary,char=>char.charCodeAt(0))));return compact&&Array.isArray(decoded)?{kind:'simlab-aas-assignment',version:1,id:decoded[0],element:decoded[1],sampleLabel:decoded[2],signal:decoded[3]}:decoded;}
function aasSubmissionPacket(run){return aasEncodePacket({kind:'simlab-aas-submission',version:1,assignmentId:run.assignmentId,sampleId:run.sampleId,studentName:run.studentName,element:run.element,mode:run.mode,standards:run.calibration.map(row=>row[0]),absorbance:run.absorbance,result:run.result,r2:run.r2,measuredAt:run.savedAt});}
window.simlabAasTeacher={
  elements:Object.values(aasElements).map(({name,symbol,range,check})=>({name,symbol,range:[...range],suggested:check})),
  restoreAssignments(records){const merged=new Map((aas.teacherAssignments||[]).map(item=>[item.id,item]));for(const item of Array.isArray(records)?records:[])if(item&&typeof item.id==='string'&&aasElements[item.element]&&typeof item.code==='string')merged.set(item.id,{...merged.get(item.id),...item});aas.teacherAssignments=[...merged.values()].slice(0,500);aasStore();return [...aas.teacherAssignments];},
  getAssignments(){let changed=false;const assignments=(aas.teacherAssignments||[]).map(item=>{if(item.code?.startsWith('SIMLAB-AAS1:')&&item.id&&aasElements[item.element]&&item.sampleLabel&&Number.isFinite(Number(item.signal))){changed=true;return {...item,code:aasEncodeCompactAssignment(item)};}return item;});if(changed){aas.teacherAssignments=assignments;aasStore();}return [...assignments];},
  getReviews(){return [...(aas.reviewedSubmissions||[])];},
  createAssignment({element,sampleLabel,concentration,studentName='',studentGroup='',folderLabel='',assignmentTitle=''}){
    const definition=aasElements[element],label=String(sampleLabel||'').trim(),value=Number(concentration);
    if(!label||label.length>40||!definition||!Number.isFinite(value)||value<definition.range[0]||value>definition.range[1])throw new Error('Enter a sample label and a concentration within the selected element’s teaching range.');
    const id=`${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`,signal=Number((.002+definition.response*value).toFixed(6)),assignment={id,element,sampleLabel:label,concentration:value,studentName:String(studentName||'').trim(),studentGroup:String(studentGroup||'').trim(),folderLabel:String(folderLabel||'').trim(),assignmentTitle:String(assignmentTitle||'').trim(),signal,createdAt:Date.now()};assignment.code=aasEncodeCompactAssignment(assignment);
    aas.teacherAssignments=[assignment,...(aas.teacherAssignments||[])];aas.lastAssignmentCode=assignment.code;aas.status=`${label} is ready to share with students.`;aasStore();return assignment;
  },
  reviewSubmission(code){
    const packet=aasDecodePacket(code);
    if(packet.kind!=='simlab-aas-submission'||packet.version!==1||typeof packet.assignmentId!=='string'||typeof packet.studentName!=='string'||!Number.isFinite(packet.result)||!Number.isFinite(packet.absorbance))throw new Error('The student result code is incomplete or invalid.');
    aas.reviewedSubmissions=[{...packet,reviewedAt:Date.now()},...(aas.reviewedSubmissions||[])].slice(0,100);
    const matched=(aas.teacherAssignments||[]).some(item=>item.id===packet.assignmentId);
    aas.status=matched?`Result received from ${packet.studentName}; teacher answer key matched.`:`Result received from ${packet.studentName}. The matching teacher answer key is not saved on this device.`;aasStore();return {packet,matched};
  }
};
function aasResetRun(){clearTimeout(aasRunTimer);const runs=aas.runs.filter(item=>item.saved),teacherAssignments=aas.teacherAssignments||[],reviewedSubmissions=aas.reviewedSubmissions||[],studentName=aas.studentName||'';aas={...aasDefault(),runs,teacherAssignments,reviewedSubmissions,studentName,status:'New run. Load a teacher-prepared unknown or choose an element to begin.'};aasStore();aasRender();}
function aasSetStatus(message){aas.status=message;aasStore();aasRender();}
